public class OperatorsObservation {
  static int original(boolean allowed) { int count=0; if (allowed) count++; return count; }
  static int forcedTrue(boolean allowed) { int count=0; if (true) count++; return count; }
  static int forcedFalse(boolean allowed) { int count=0; if (false) count++; return count; }
  static int negated(boolean allowed) { int count=0; if (!allowed) count++; return count; }
  static class Counter { int count; void increment() { count++; } }
  public static void main(String[] args) {
    for (boolean allowed: new boolean[]{false,true}) {
      System.out.printf("condition %s %d %d %d %d%n",allowed,original(allowed),forcedTrue(allowed),forcedFalse(allowed),negated(allowed));
    }
    Counter present=new Counter(); present.increment(); Counter omitted=new Counter();
    System.out.printf("void-state %d %d%n",present.count,omitted.count);
    int up=5;up++;int down=5;down--;
    System.out.printf("local-increment %d %d%n",up,down);
  }
}
